  ('demo','Customer','Alumdoor','0','0','0','1','{"name":"Customer","kind":"master","label":"Khách hàng","module":"Alumdoor","is_child":false,"is_tree":false,"is_single":false,"is_submittable":false,"track_changes":true,"allow_rename":false,"autoname":"field:customer_name","title_field":"customer_name","search_fields":["customer_name","contact_person","phone","tax_id"],"fields":[{"fieldname":"customer_name","label":"Tên khách hàng","fieldtype":"Data","required":true,"unique":true,"in_list_view":true,"in_standard_filter":false,"valueSource":"user","editMode":"editable","surface":"quick","serverEnforced":false,"idx":1},{"label":"Nhóm giá","//":"NHÓM GIÁ — trường quyết định, không phải `customer_type`.","//vi-sao":["Hai thứ này trông giống nhau nên rất dễ nhập một chỗ rồi tưởng chỗ kia cũng đúng.","Cột phân loại cũ trong file nạp KHÔNG đáng tin: 321/439","khách đang mang đúng giá trị mặc định ''Đại lý'', 114 khách để ''Khác'', chỉ 4 khách là","''Khách lẻ''. Bốn khách lẻ trên bốn trăm ba chín là con số không thể có thật.","","Nhóm giá thì quyết định TIỀN và cả KÍCH THƯỚC CẮT NHÔM (đại lý đo phủ bì nhựa trừ","0,02; khách lẻ đo phủ bì ray trừ 0,08 — xem docs/ALUMDOOR-LUAT-DO-VA-GIA.md). Sai một","khách là vừa sai tiền vừa cắt hỏng cây nhôm, nên nó phải là một trường riêng, KHÔNG","mặc định, và để trống thì chứng từ bị từ chối chứ không đoán.","","Chỉ hai giá trị: chủ xưởng chốt Công trình và Nhà thầu tính như khách lẻ."],"fieldname":"price_group","fieldtype":"Select","options":"Đại lý\nLẻ","in_list_view":true,"in_standard_filter":true,"description":"Quyết định cách đo bề rộng và giá bán. Đại lý đo phủ bì nhựa, khách lẻ đo phủ bì ray. Công trình và nhà thầu tính như khách lẻ.","valueSource":"user","editMode":"editable","surface":"expanded","serverEnforced":false,"idx":2},{"label":"Nhân viên bán hàng","fieldname":"account_manager","fieldtype":"Link","options":"Employee","link_filters":"{\"employee_status\":\"Đang làm việc\"}","description":"Nhân viên bán hàng đang phụ trách